// ─── conversations ──────────────────────────────────────────────────────────
export const conversations = pgTable('conversations', {
  pinned: boolean('pinned').notNull().default(false),
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  userId: text('user_id').notNull(),
  /** Short public id for URLs (/c/<slug>). */
  slug: text('slug').notNull().unique().$defaultFn(() => shortId()),
  title: text('title').notNull().default('New conversation'),
  sdkSessionId: text('sdk_session_id'),
  /** claude = plain Claude (the persona only learns from it); clone = answer AS the clone (to test it). */
  mode: text('mode').$type<'claude' | 'clone'>().notNull().default('claude'),
  /** Per-conversation overrides; null → org default. */
  model: text('model'),
  effort: text('effort').$type<'low' | 'medium' | 'high' | 'xhigh' | 'max'>(),
  status: text('status').$type<'live' | 'idle' | 'closed'>().notNull().default('idle'),
  /** Per-conversation working directory for code execution + file outputs (null = legacy per-clone workspace). */
  cwd: text('cwd'),
  /** POWER: absolute path of the granted folder this conversation runs in (null = sandbox).
   *  Bound at creation, immutable after the first message. */
  workspace: text('workspace'),
  /** The cwd the current sdk_session_id was minted in — resume only when it matches. */
  resumeCwd: text('resume_cwd'),
  extractedAt: timestamp('extracted_at', { withTimezone: true }),
  lastActivityAt: timestamp('last_activity_at', { withTimezone: true }).defaultNow().notNull(),
  createdAt: now(),
}, (t) => [index('conversations_clone_idx').on(t.cloneId, t.lastActivityAt)]);

