// ─── reasoning fingerprint (how the human thinks — not what they did) ───────
export type ReasoningDimension =
  | 'decomposition'        // how they break a problem down (units, backwards from goal, by analogy…)
  | 'starting_point'       // evidence-first vs hypothesis-first; simplest case vs general case
  | 'information'          // what they ask for / trust: examples vs rules, why before how, must see it
  | 'verification'         // how they check themselves: second route, test, move on
  | 'explanation'          // how they like things explained back
  | 'risk'                 // caution, reversibility, when they escalate
  | 'pace'                 // breadth-first exploring vs narrow-and-deep; patience
  | 'other';

/** One reasoning move observed in one conversation. Domain-free by construction. */
export const reasoningObservations = pgTable('reasoning_observations', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  patternKey: text('pattern_key').notNull(),      // snake_case id the extractor reuses across chats
  dimension: text('dimension').$type<ReasoningDimension>().notNull(),
  description: text('description').notNull(),     // one domain-free sentence, present tense
  evidence: jsonb('evidence').$type<Evidence[]>().notNull().default([]),
  weight: real('weight').notNull().default(1),    // negative = counter-evidence ("not me")
  sourceKind: text('source_kind').$type<'conversation' | 'import' | 'feedback'>().notNull(),
  sourceRef: text('source_ref').notNull(),        // conversation id / import conversation uuid
  createdAt: now(),
}, (t) => [index('reasoning_obs_clone_idx').on(t.cloneId, t.patternKey)]);

/** Aggregated pattern: strength grows with repeated, independent evidence and decays over time. */
export const reasoningPatterns = pgTable('reasoning_patterns', {
  cloneId: uuid('clone_id').notNull(),
  patternKey: text('pattern_key').notNull(),
  orgId: text('org_id').notNull(),
  dimension: text('dimension').$type<ReasoningDimension>().notNull(),
  description: text('description').notNull(),
  strength: real('strength').notNull().default(0),
  nSources: integer('n_sources').notNull().default(0),   // distinct conversations that showed it
  status: text('status').$type<'emerging' | 'confirmed' | 'rejected'>().notNull().default('emerging'),
  userVerdict: text('user_verdict').$type<'accept' | 'reject'>(),
  examples: jsonb('examples').$type<string[]>().notNull().default([]),
  firstSeenAt: timestamp('first_seen_at', { withTimezone: true }).defaultNow().notNull(),
  lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: updated(),
}, (t) => [primaryKey({ columns: [t.cloneId, t.patternKey] })]);

/** "That's me" / "Not me" on a clone reply. */
export const reasoningFeedback = pgTable('reasoning_feedback', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  conversationId: uuid('conversation_id').notNull(),
  turnId: uuid('turn_id').notNull(),
  verdict: text('verdict').$type<'me' | 'not_me'>().notNull(),
  comment: text('comment'),
  userId: text('user_id').notNull(),
  createdAt: now(),
}, (t) => [index('reasoning_feedback_clone_idx').on(t.cloneId, t.createdAt)]);

/** claude.ai data-export import runs. */
export const importJobs = pgTable('import_jobs', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  userId: text('user_id').notNull(),
  filename: text('filename').notNull(),
  status: text('status').$type<'queued' | 'running' | 'done' | 'failed'>().notNull().default('queued'),
  total: integer('total').notNull().default(0),
  processed: integer('processed').notNull().default(0),
  skipped: integer('skipped').notNull().default(0),
  observations: integer('observations').notNull().default(0),
  error: text('error'),
  createdAt: now(),
  updatedAt: updated(),
});

// ─── Claude Code ingestion ──────────────────────────────────────────────────
/** Personal tokens used by the Claude Code SessionEnd hook to post transcripts. Stored hashed. */
export const ingestTokens = pgTable('ingest_tokens', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  userId: text('user_id').notNull(),
  name: text('name').notNull().default('Claude Code'),
  tokenHash: text('token_hash').notNull().unique(),
  lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
  createdAt: now(),
});

/** One row per Claude Code session we have learned from (dedupe + resume). */
export const claudeCodeSessions = pgTable('claude_code_sessions', {
  cloneId: uuid('clone_id').notNull(),
  sessionId: text('session_id').notNull(),
  orgId: text('org_id').notNull(),
  source: text('source').$type<'local' | 'hook' | 'upload' | 'bridge' | 'claude-chat'>().notNull(),
  project: text('project'),
  bytes: integer('bytes').notNull().default(0),
  humanTurns: integer('human_turns').notNull().default(0),
  observations: integer('observations').notNull().default(0),
  status: text('status').$type<'queued' | 'done' | 'skipped' | 'failed'>().notNull().default('queued'),
  note: text('note'),
  extractedAt: timestamp('extracted_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [primaryKey({ columns: [t.cloneId, t.sessionId] })]);

/** opersona bridge pairing tokens (obr_… , stored as sha256). One row per paired machine. */
export const bridgeTokens = pgTable('bridge_tokens', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  userId: text('user_id').notNull(),
  name: text('name').notNull().default('my machine'),
  // Constraint name + plain timestamp match the DDL production was built with (pre-baseline).
  tokenHash: text('token_hash').notNull().unique('bridge_tokens_token_hash_key'),
  createdAt: timestamp('created_at').defaultNow().notNull(),
  lastSeenAt: timestamp('last_seen_at'),
  revokedAt: timestamp('revoked_at'),
}, (t) => [index('bridge_tokens_org_idx').on(t.orgId)]);

// ─── self-tests ("does it sound like me?") ──────────────────────────────────
export const selfTests = pgTable('self_tests', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  batchId: uuid('batch_id').notNull(),
  domain: text('domain').notNull().default(''),
  question: text('question').notNull(),
  answer: text('answer').notNull(),
  model: text('model'),
  verdict: text('verdict').$type<'me' | 'not_me'>(),
  comment: text('comment'),
  ratedAt: timestamp('rated_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [index('self_tests_clone_idx').on(t.cloneId, t.createdAt)]);

// ─── personality (self-reported MBTI-style lens) ────────────────────────────
export const personalityTests = pgTable('personality_tests', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  answers: jsonb('answers').$type<Record<string, number>>().notNull(),
  scores: jsonb('scores').$type<Record<'EI' | 'SN' | 'TF' | 'JP', number>>().notNull(),
  type: text('type').notNull(),
  // 'test' = scored from Likert answers; 'stated' = the owner typed their four
  // letters in directly (scores are ±1 direction sentinels — never render as %).
  source: text('source').$type<'test' | 'stated'>().notNull().default('test'),
  createdAt: now(),
}, (t) => [index('personality_clone_idx').on(t.cloneId, t.createdAt)]);

// auth abuse tracking — per-account lockout (defeats distributed password spray that IP limits miss)
export const authFailures = pgTable('auth_failures', {
  id: uuid('id').primaryKey().defaultRandom(),
  email: text('email').notNull(),
  createdAt: now(),
}, (t) => [index('auth_failures_email_idx').on(t.email, t.createdAt)]);

// ─── community: publish / grants / reports / imports (0018) ─────────────────

/** A persona the owner chose to publish. `artifact` is the frozen `opersona/persona@1` snapshot — republish bumps `version` and replaces it. */
export const publishedPersonas = pgTable('published_personas', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull().unique('published_personas_clone_uq'),
  ownerUserId: text('owner_user_id').notNull(),
  slug: text('slug').notNull().unique('published_personas_slug_uq'),
  artifact: jsonb('artifact').$type<PersonaArtifact>().notNull(),
  /** Which sections the owner included at publish time (facts/playbooks/personality toggles). */
  sections: jsonb('sections').$type<Record<string, boolean>>().notNull().default({}),
  /** Owner-sovereign: 'public' (anyone, incl. logged out) or 'restricted' (author + granted people). Private = not published. */
  visibility: text('visibility').$type<'public' | 'restricted'>().notNull().default('restricted'),
  /** 'active' | 'unpublished' (owner took it down) | 'delisted' (moderation). Non-active → /p 404s; existing imports keep working. */
  status: text('status').$type<'active' | 'unpublished' | 'delisted'>().notNull().default('active'),
  version: integer('version').notNull().default(1),
  importCount: integer('import_count').notNull().default(0),
  publishedAt: timestamp('published_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: updated(),
  unpublishedAt: timestamp('unpublished_at', { withTimezone: true }),
}, (t) => [index('published_personas_browse_idx').on(t.visibility, t.status, t.importCount)]);

/** Restricted-visibility access grants, by email (pending until that email has an account). */
export const personaGrants = pgTable('persona_grants', {
  id: uuid('id').primaryKey().defaultRandom(),
  publishedId: uuid('published_id').notNull(),
  granteeEmail: text('grantee_email').notNull(),
  granteeUserId: text('grantee_user_id'),
  createdAt: now(),
}, (t) => [unique('persona_grants_uq').on(t.publishedId, t.granteeEmail), index('persona_grants_pub_idx').on(t.publishedId)]);

export const personaReports = pgTable('persona_reports', {
  id: uuid('id').primaryKey().defaultRandom(),
  publishedId: uuid('published_id').notNull(),
  reporterUserId: text('reporter_user_id'),
  reason: text('reason').notNull(),
  details: text('details'),
  createdAt: now(),
  resolvedAt: timestamp('resolved_at', { withTimezone: true }),
  resolution: text('resolution'),
}, (t) => [index('persona_reports_open_idx').on(t.resolvedAt, t.createdAt)]);

/** Provenance for an imported (materialized) persona living as a local clone with kind='imported'. */
export const importedPersonas = pgTable('imported_personas', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull().unique('imported_personas_clone_uq'),
  importedBy: text('imported_by').notNull(),
  sourcePublishedId: uuid('source_published_id'),
  sourceSlug: text('source_slug'),
  sourceVersion: integer('source_version').notNull(),
  artifact: jsonb('artifact').$type<PersonaArtifact>().notNull(),
  createdAt: now(),
  updatedAt: updated(),
}, (t) => [index('imported_personas_org_idx').on(t.orgId)]);

// ─── cognitive interview + knowledge model (P2) ─────────────────────────────
// The interview asks behavioural questions across ten life categories; every
// answer is analysed into MEMORIES (things that happened), TRAITS (values /
// beliefs / preferences / behaviours / decision patterns) and CONTEXTUAL RULES
// (IF situation AND condition THEN tendency). Each learned item carries the
// provenance spine PLUS an epistemic `tier`: 'explicit' (they plainly said it),
// 'inferred' (observed across answers), 'hypothesis' (suspected). Tiers never
// auto-promote — only new explicit quoted evidence or an owner verdict moves one.

export type InterviewQuestionKind = 'behavioural' | 'follow_up' | 'contradiction';
export type InterviewQuestionSource = 'bank' | 'generated' | 'triage';
export type InterviewQuestionStatus = 'pending' | 'asked' | 'answered' | 'skipped' | 'retired';
export type EpistemicTier = 'explicit' | 'inferred' | 'hypothesis';
export type TraitKind = 'value' | 'belief' | 'preference' | 'behaviour' | 'decision_pattern';

export const interviewQuestions = pgTable('interview_questions', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  category: text('category').notNull(),
  /** Sub-area within the category the question probes (bank facets; nullable for follow-ups). */
  facet: text('facet'),
  text: text('text').notNull(),
  /** One quiet line under the question ("a real moment beats a general answer"). */
  hint: text('hint'),
  kind: text('kind').$type<InterviewQuestionKind>().notNull().default('behavioural'),
  source: text('source').$type<InterviewQuestionSource>().notNull().default('bank'),
  /** Follow-up intent (why | alternatives | what_mattered | would_you_today | exception | close_person). */
  intent: text('intent'),
  parentAnswerId: uuid('parent_answer_id'),
  contradictionId: uuid('contradiction_id'),
  /** Stable bank id so an opener is materialized at most once per clone. */
  bankKey: text('bank_key'),
  status: text('status').$type<InterviewQuestionStatus>().notNull().default('pending'),
  priority: real('priority').notNull().default(0),
  askedAt: timestamp('asked_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [
  index('interview_questions_clone_status_idx').on(t.cloneId, t.status),
  uniqueIndex('interview_questions_bank_uq').on(t.cloneId, t.bankKey).where(sql`bank_key is not null`),
]);

export const interviewAnswers = pgTable('interview_answers', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  questionId: uuid('question_id').notNull(),
  /** Denormalized so the answer stays self-describing even if the question is retired. */
  category: text('category').notNull(),
  questionText: text('question_text').notNull(),
  text: text('text').notNull().default(''),
  skipped: boolean('skipped').notNull().default(false),
  context: jsonb('context').$type<{ threadDepth?: number; intent?: string | null; dialogue?: { role: string; text: string }[] }>().notNull().default({}),
  /** Edits never erase: prior versions pushed here. */
  revisions: jsonb('revisions').$type<{ text: string; at: string }[]>().notNull().default([]),
  /** Summary of what the async pass extracted (for the answer history UI). */
  extraction: jsonb('extraction').$type<{ memories: number; traits: number; rules: number; tensions: number; quality: string; note: string } | null>().default(null),
  extractionStatus: text('extraction_status').$type<'pending' | 'done' | 'failed' | 'skipped'>().notNull().default('pending'),
  extractedAt: timestamp('extracted_at', { withTimezone: true }),
  editedAt: timestamp('edited_at', { withTimezone: true }),
  createdAt: now(),
}, (t) => [
  index('interview_answers_clone_idx').on(t.cloneId, t.createdAt),
  index('interview_answers_extract_idx').on(t.cloneId, t.extractionStatus),
]);

/** Life memories — things that HAPPENED, separate from behaviour patterns.
 *  "Moved cities in 2024 for work" is a memory; "willing to relocate for career
 *  upside" is a trait. */
export const memories = pgTable('memories', {
  id: uuid('id').primaryKey().defaultRandom(),
  ...spine(),
  summary: text('summary').notNull(),
  fullContext: text('full_context').notNull().default(''),
  importance: real('importance').notNull().default(0.5),
  emotionalSignificance: real('emotional_significance').notNull().default(0),
  peopleInvolved: text('people_involved').array().notNull().default(sql`'{}'::text[]`),
  /** Verbatim fuzzy period as the person said it ("2024", "when I was a kid"). */
  dateOrPeriod: text('date_or_period'),
  periodStart: timestamp('period_start', { withTimezone: true }),
  periodEnd: timestamp('period_end', { withTimezone: true }),
  category: text('category'),
  shareable: boolean('shareable').notNull().default(false),
  tsv: tsvector('tsv').generatedAlwaysAs(sql`to_tsvector('english', coalesce(summary,'') || ' ' || coalesce(full_context,'') || ' ' || coalesce(date_or_period,''))`),
}, (t) => [
  index('memories_clone_idx').on(t.cloneId, t.status),
  index('memories_tsv_idx').using('gin', t.tsv),
]);

/** Values / beliefs / preferences / behaviours / decision patterns, keyed for
 *  reinforcement (same key ⇒ evidence accumulates instead of duplicating). */
export const traits = pgTable('traits', {
  id: uuid('id').primaryKey().defaultRandom(),
  ...spine(),
  kind: text('kind').$type<TraitKind>().notNull(),
  key: text('key').notNull(),
  /** Short display name, e.g. "Independence". */
  label: text('label').notNull(),
  /** One-sentence statement of the trait. */
  statement: text('statement').notNull(),
  category: text('category'),
  tier: text('tier').$type<EpistemicTier>().notNull(),
  /** How strongly held (≠ confidence, which is how sure WE are). */
  strength: real('strength').notNull().default(0.5),
  contexts: text('contexts').array().notNull().default(sql`'{}'::text[]`),
  shareable: boolean('shareable').notNull().default(false),
  validFrom: timestamp('valid_from', { withTimezone: true }),
  validUntil: timestamp('valid_until', { withTimezone: true }),
  tsv: tsvector('tsv').generatedAlwaysAs(sql`to_tsvector('english', coalesce(label,'') || ' ' || coalesce(statement,'') || ' ' || coalesce(category,''))`),
}, (t) => [
  uniqueIndex('traits_clone_kind_key_uq').on(t.cloneId, t.kind, t.key),
  index('traits_clone_idx').on(t.cloneId, t.status),
  index('traits_tsv_idx').using('gin', t.tsv),
]);

/** Conditional behaviour: IF situation (AND condition) THEN tendency. The
 *  simulation consults these — and exceptions — before predicting. */
export const contextualRules = pgTable('contextual_rules', {
  id: uuid('id').primaryKey().defaultRandom(),
  ...spine(),
  category: text('category'),
  situation: text('situation').notNull(),
  condition: text('condition'),
  tendency: text('tendency').notNull(),
  /** When this rule is an exception to a trait, the trait it bends. */
  exceptionToTraitId: uuid('exception_to_trait_id'),
  tier: text('tier').$type<'explicit' | 'inferred'>().notNull(),
  shareable: boolean('shareable').notNull().default(false),
  validFrom: timestamp('valid_from', { withTimezone: true }),
  validUntil: timestamp('valid_until', { withTimezone: true }),
  tsv: tsvector('tsv').generatedAlwaysAs(sql`to_tsvector('english', coalesce(situation,'') || ' ' || coalesce(condition,'') || ' ' || coalesce(tendency,''))`),
}, (t) => [
  index('contextual_rules_clone_idx').on(t.cloneId, t.status),
  index('contextual_rules_tsv_idx').using('gin', t.tsv),
]);

/** Detected tensions between what the model believes and a new answer — each
 *  gets a targeted probe question; a resolution usually becomes a contextual rule. */
export const contradictions = pgTable('contradictions', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  traitId: uuid('trait_id'),
  answerId: uuid('answer_id').notNull(),
  description: text('description').notNull(),
  probeQuestionId: uuid('probe_question_id'),
  status: text('status').$type<'open' | 'probed' | 'resolved' | 'dismissed'>().notNull().default('open'),
  resolutionAnswerId: uuid('resolution_answer_id'),
  resolutionNote: text('resolution_note'),
  createdAt: now(),
  resolvedAt: timestamp('resolved_at', { withTimezone: true }),
}, (t) => [index('contradictions_clone_status_idx').on(t.cloneId, t.status)]);

/** Per-category coverage cache, recomputed after each extraction. */
export const interviewCoverage = pgTable('interview_coverage', {
  cloneId: uuid('clone_id').notNull(),
  category: text('category').notNull(),
  orgId: text('org_id').notNull(),
  coverage: real('coverage').notNull().default(0),
  facets: jsonb('facets').$type<Record<string, number>>().notNull().default({}),
  answered: integer('answered').notNull().default(0),
  openContradictions: integer('open_contradictions').notNull().default(0),
  updatedAt: updated(),
}, (t) => [primaryKey({ columns: [t.cloneId, t.category] })]);

/** Vendor-free embedding store (written only when EMBEDDINGS_PROVIDER is set;
 *  FTS stays the default retrieval). vec is jsonb so a later pgvector swap is a
 *  column change, not a schema redesign. */
export const knowledgeEmbeddings = pgTable('knowledge_embeddings', {
  itemKind: text('item_kind').$type<'memory' | 'trait' | 'rule'>().notNull(),
  itemId: uuid('item_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  orgId: text('org_id').notNull(),
  provider: text('provider').notNull(),
  model: text('model').notNull(),
  dim: integer('dim').notNull(),
  vec: jsonb('vec').$type<number[]>().notNull(),
  createdAt: now(),
}, (t) => [primaryKey({ columns: [t.itemKind, t.itemId] }), index('knowledge_embeddings_clone_idx').on(t.cloneId)]);

// ─── blind prediction tests (P4) ────────────────────────────────────────────
// The self-honesty loop: the model predicts BLIND (at scenario creation, sealed
// until the person commits their own answer — predicted_at < answered_at is a
// stored invariant), then an LLM judge scores the match across dimensions.
// Operational like self_tests, NOT spine(): a test artifact, not a learned layer.

export interface ScenarioPrediction { decision: string; factors: string[]; communication: string; confidence: number }
export interface ScenarioJudgeOut { rationale: Record<string, string>; key_differences: string[]; summary: string }

export const predictionScenarios = pgTable('prediction_scenarios', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  batchId: uuid('batch_id').notNull(),
  category: text('category').notNull(),
  format: text('format').$type<'open' | 'choice'>().notNull().default('open'),
  choices: text('choices').array().notNull().default(sql`'{}'::text[]`),
  scenario: text('scenario').notNull(),
  question: text('question').notNull(),
  /** Why this scenario was generated (which weak/uncertain areas it targets). */
  targetNote: text('target_note'),
  targetRefs: jsonb('target_refs').$type<{ kind: string; ref: string; hint?: string }[]>().notNull().default([]),
  snapshotVersion: integer('snapshot_version'),
  model: text('model'),
  // Sealed until answered — never selected into any open-scenario payload.
  aiPrediction: jsonb('ai_prediction').$type<ScenarioPrediction>(),
  predictedAt: timestamp('predicted_at', { withTimezone: true }),
  // State machine: open → answered → scored | failed ; open → skipped.
  status: text('status').$type<'open' | 'answered' | 'scored' | 'skipped' | 'failed'>().notNull().default('open'),
  humanAnswer: text('human_answer'),
  humanFactors: text('human_factors'),
  answeredAt: timestamp('answered_at', { withTimezone: true }),
  judge: jsonb('judge').$type<ScenarioJudgeOut>(),
  scoreDecision: real('score_decision'),
  scoreReasoning: real('score_reasoning'),
  scorePreference: real('score_preference'),
  scoreCommunication: real('score_communication'),
  scoreCalibration: real('score_calibration'),
  scoreOverall: real('score_overall'),
  judgeModel: text('judge_model'),
  judgedAt: timestamp('judged_at', { withTimezone: true }),
  correctionId: uuid('correction_id'),
  createdAt: now(),
}, (t) => [
  index('pred_scenarios_clone_status_idx').on(t.cloneId, t.status),
  index('pred_scenarios_clone_idx').on(t.cloneId, t.createdAt),
]);

// ─── simulations (P5) ───────────────────────────────────────────────────────
// One-shot behavioural predictions ("what would I do?"). Deliberately NOT
// conversations: server-assembled context, structured output, and the learning
// queue never mines them (they are the persona talking, not the human).

export interface SimulationOutput {
  answer: string;
  factors: { factor: string; weight: 'major' | 'minor' }[];
  confidence: number;
  uncertainty: string[];
  evidence_used: string[];
  enough_information: boolean;
  comparison?: { option: string; verdict: string; lean: number }[];
}

export const simulations = pgTable('simulations', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  userId: text('user_id').notNull(),
  mode: text('mode').$type<'ask' | 'respond' | 'decide' | 'compare' | 'explain'>().notNull(),
  input: jsonb('input').$type<{ text: string; options?: string[]; context?: string }>().notNull(),
  output: jsonb('output').$type<SimulationOutput>().notNull(),
  /** The retrieval hits that were OFFERED to the model (evidence_used ⊆ these ids). */
  evidence: jsonb('evidence').$type<{ layer: string; id: string; text: string }[]>().notNull().default([]),
  model: text('model'),
  createdAt: now(),
}, (t) => [index('simulations_clone_idx').on(t.cloneId, t.createdAt)]);

/** Chat-style interview: the persona messages its human; short exchanges per
 *  question. When a thread wraps, the user side materializes into an
 *  interview_answers row (same extraction pipeline; quotes stay verifiable
 *  against the person's own words). */
export const interviewMessages = pgTable('interview_messages', {
  id: uuid('id').primaryKey().defaultRandom(),
  orgId: text('org_id').notNull(),
  cloneId: uuid('clone_id').notNull(),
  questionId: uuid('question_id').notNull(),
  role: text('role').$type<'interviewer' | 'user'>().notNull(),
  text: text('text').notNull(),
  createdAt: now(),
}, (t) => [index('interview_messages_thread_idx').on(t.cloneId, t.questionId, t.createdAt)]);
